examples.template:
Column(verticalArrangement = Arrangement.spacedBy(MonarchTheme.spacing.space4)) {
    MonarchTextField(
        value = name,
        onValueChange = { name = it },
        label = "Workspace name",
        required = true,
        placeholder = "Acme Inc.",
        errorText = nameError,
    )
    MonarchUsernameAvailabilityInput(
        value = username,
        label = "Workspace username",
        required = true,
        onValueChange = { username = it },
        validate = { handle ->
            when {
                handle.any { !it.isLetterOrDigit() || it.code > 127 } ->
                    MonarchUsernameAvailabilityResult(valid = false, message = "Use letters and numbers only")
                handle.length !in 5..30 -> MonarchUsernameAvailabilityResult(valid = false, message = "Use 5 to 30 characters")
                // Call the product's availability lookup here.
                else -> MonarchUsernameAvailabilityResult(valid = handle.lowercase() != "acmeinc")
            }
        },
        placeholder = "acme",
        helperText = "Letters and numbers only, 5 to 30 characters.",
        prefix = "@",
        onStatusChange = { status, _ -> usernameStatus = status },
    )
    MonarchRadioCardGroup(
        options = listOf(
            MonarchRadioCardOption(
                "creator",
                title = "Creator",
                description = "For individual creators and personal projects",
                icon = { MonarchIcon(SampleIcons.Person, contentDescription = null) },
            ),
            MonarchRadioCardOption(
                "business",
                title = "Business",
                description = "For teams and companies",
                icon = { MonarchIcon(SampleIcons.Building, contentDescription = null) },
            ),
        ),
        selected = type,
        onSelect = { type = it },
        label = "Type",
        columns = 2,
        layout = MonarchRadioCardLayout.Tile,
    )
    if (submitted && type == null) {
        MonarchText(
            text = "Choose a workspace type",
            style = MonarchTextStyle.Caption,
            color = MonarchTheme.colors.dangerStrong,
        )
    }
    MonarchButton(
        text = "Continue",
        onClick = {
            submitted = true
            if (nameError == null && name.isNotBlank() && type != null && usernameStatus == MonarchUsernameAvailabilityStatus.Valid) {
                creating = true
                // Create the workspace, then set creating to false.
            }
        },
        modifier = Modifier.fillMaxWidth(),
        variant = MonarchButtonVariant.Primary,
        loading = creating,
    )
}

examples.setupTemplate:
var name by rememberSaveable { mutableStateOf({{name}}) }
var username by rememberSaveable { mutableStateOf({{username}}) }
var type by rememberSaveable { mutableStateOf<String?>(null) }
var usernameStatus by remember { mutableStateOf(MonarchUsernameAvailabilityStatus.Idle) }
var submitted by rememberSaveable { mutableStateOf(false) }
var creating by remember { mutableStateOf(false) }
val length = name.trim().length
val nameError = when {
    !submitted && length == 0 -> null
    length < 4 -> "Name must be at least 4 characters"
    length > 25 -> "Name must be at most 25 characters"
    else -> null
}

